&= \left(\tfrac{a}{b}-\tfrac{b}{a}+\tfrac{b}{c}-\tfrac{c}{b}\right) + \left(\tfrac{c}{d}-\tfrac{d}{c}+\tfrac{d}{a}-\tfrac{a}{d}\right)
