dot(" $E$ ", E, dir(80));
dot(" $F$ ", F, dir(-80));
dot(" $O_\mathcal{P}$ ", O1, dir(200));
dot(" $O_\mathcal{Q}$ ", O2, dir(45));
dot(" ", 0.5(B+C), dir(-90));
