\begin{align*}
abcd+16 &=ab+bc+cd+da+16\left(\frac{1}{ab}+\frac{1}{bc}+\frac{1}{cd}+\frac{1}{da}\right)  &=ab+\frac{16}{bc}+cd+\frac{16}{da}+bc+\frac{16}{cd}+da+\frac{16}{ab}  &\ge 8\left(\sqrt \frac{a}{c}+\sqrt \frac{c}{a} \right)+8\left(\sqrt \frac{b}{d} +\sqrt \frac{d}{b} \right)  &=8\left(\sqrt {\frac{a}{c}+2+\frac{c}{a}}\right)+8\left(\sqrt {\frac{b}{d}+2+\frac{d}{b}}\right)  &=8 \sqrt{(a+c)\left(\frac{1}{a} + \frac{1}{c}\right)}+8\sqrt{(b+d)\left(\frac{1}{b}+\frac{1}{d}\right)}. \quad \blacksquare
\end{align*}

